import{_ as t,o as i,c as a,a0 as s}from"./chunks/framework.BFac62L4.js";const u=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment/docker.md","filePath":"guide/deployment/docker.md"}'),o={name:"guide/deployment/docker.md"};function n(l,e,r,c,h,p){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>This section will help you spin up Authup as a <strong>docker</strong> container.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><p>The following guide is based on some shared assumptions:</p><ul><li>Docker <code>v20.x</code> is <a href="https://docs.docker.com/get-docker/" target="_blank" rel="noreferrer">installed</a></li><li>Min. <code>2</code> cores</li><li>Min. <code>5G</code> hard disk</li><li>One available port on the host system if you want to map the service to your local machine (default: <code>3000</code>)</li></ul><h2 id="step-1-create-a-new-project" tabindex="-1">Step. 1: Create a new project <a class="header-anchor" href="#step-1-create-a-new-project" aria-label="Permalink to &quot;Step. 1: Create a new project&quot;">​</a></h2><p>Create and change into a new directory.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">$</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mkdir</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> authup</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &amp;&amp; </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> authup</span></span></code></pre></div><h2 id="step-2-configuration" tabindex="-1">Step. 2: Configuration <a class="header-anchor" href="#step-2-configuration" aria-label="Permalink to &quot;Step. 2: Configuration&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>It is important to mention that in the docker environment the configuration for the <code>PORT</code> option is ignored.</p></div><p>So when the authup container is run, the rule is as follows:</p><ul><li>The API always runs on the internal port <code>3000</code> and can be mounted on another external port (<code>-p &lt;port&gt;:3000</code>). The <code>console</code> role is the exception: each console binds its own port (<code>3020</code> auth, <code>3021</code> admin, <code>3022</code> account), see <a href="./console-replicas.html">Console Replicas</a>.</li></ul><p>Follow the instructions for <a href="./configuration.html">configuring</a> Authup using a configuration file or via environment variables. In case of a configuration file, mount it into the container&#39;s working directory using <code>-v ./authup.yml:/usr/src/app/authup.yml</code>.</p><h2 id="step-3-boot-up" tabindex="-1">Step. 3: Boot up <a class="header-anchor" href="#step-3-boot-up" aria-label="Permalink to &quot;Step. 3: Boot up&quot;">​</a></h2><p>One container runs the whole deployment. It serves the API and every console:</p><div class="language-shell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -v</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> authup:/var/lib/authup</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 3001:3000</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUBLIC_URL=http://localhost:3001</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  authup/authup:latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server/core</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p><code>PUBLIC_URL</code> is the address the browser reaches the container at. The consoles derive the API address from it, so with the port published as <code>3001</code> it must name <code>3001</code>, not the container-internal <code>3000</code>.</p><p>Now all should be set up, and you are ready to go 🎉</p><p>This will launch the following with default settings:</p><ul><li>API: <code>http://localhost:3001/</code></li><li>Auth console (login, consent, register, password recovery): <code>http://localhost:3001/console/auth</code></li><li>Admin console: <code>http://localhost:3001/console/admin</code></li><li>Account console: <code>http://localhost:3001/console/account</code></li></ul><div class="warning custom-block"><p class="custom-block-title">The <code>client/admin-console</code> service was retired</p><p>The admin console used to be a second container. It is now a console service composed into <code>server/core start</code>, and <code>client/admin-console start</code> exits with an error naming the replacement. See <a href="./upgrading.html">Upgrading</a>.</p></div><p>It is recommended to operate the service behind a reverse proxy. For example <a href="./nginx.html">nginx</a>.</p>`,22)])])}const k=t(o,[["render",n]]);export{u as __pageData,k as default};
